package android.os;import java.util.*;public class Bundle{private final Map<String,Object> v=new HashMap<>();public void putBoolean(String k,boolean x){v.put(k,x);}public void putInt(String k,int x){v.put(k,x);}public void putString(String k,String x){v.put(k,x);}public boolean getBoolean(String k){return (boolean)v.getOrDefault(k,false);}public int getInt(String k){return (int)v.getOrDefault(k,0);}public String getString(String k){return (String)v.get(k);}}
